import { Project, Task, TaskFilter, TaskRepository, User } from "../domain/task";

export class InMemoryTaskRepository implements TaskRepository {
  private readonly users = new Map<string, User>();
  private readonly projects = new Map<string, Project>();
  private readonly tasks = new Map<string, Task>();

  public addUser(user: User): void {
    this.users.set(user.id, user);
  }

  public findUser(id: string): User | undefined {
    return this.users.get(id);
  }

  public addProject(project: Project): void {
    this.projects.set(project.id, project);
  }

  public findProject(id: string): Project | undefined {
    return this.projects.get(id);
  }

  public addTask(task: Task): void {
    this.tasks.set(task.id, task);
  }

  public findTask(id: string): Task | undefined {
    return this.tasks.get(id);
  }

  public tasksForProject(projectId: string, filter: TaskFilter): Task[] {
    return [...this.tasks.values()].filter(
      (task) =>
        task.projectId === projectId &&
        (filter.status === undefined || task.status === filter.status) &&
        (filter.assigneeId === undefined || task.assigneeId === filter.assigneeId),
    );
  }
}

